GUEST_SCRIPT = r'''
from pathlib import Path
from PIL import Image, ImageFilter
from statistics import fmean
from math import sqrt
import base64, glob, hashlib, json, os, socket, struct, urllib.parse, urllib.request

spec = json.loads(__SPEC_JSON__)

def metrics(image):
    reduced = image.convert("RGB").resize((64, 64), Image.Resampling.LANCZOS)
    pixels = list(reduced.getdata())
    luminances = [0.2126*r + 0.7152*g + 0.0722*b for r, g, b in pixels]
    mean_luminance = fmean(luminances)
    return {
        "lum_mean": mean_luminance,
        "lum_std": sqrt(fmean((value-mean_luminance)**2 for value in luminances)),
        "chroma": fmean(max(pixel)-min(pixel) for pixel in pixels),
        "edge": fmean(reduced.filter(ImageFilter.FIND_EDGES).convert("L").getdata()),
        "r": fmean(pixel[0] for pixel in pixels),
        "g": fmean(pixel[1] for pixel in pixels),
        "b": fmean(pixel[2] for pixel in pixels),
    }

def correlation(left, right):
    a = list(left.convert("L").resize((64, 64), Image.Resampling.LANCZOS).getdata())
    b = list(right.convert("L").resize((64, 64), Image.Resampling.LANCZOS).getdata())
    am, bm = fmean(a), fmean(b)
    denominator = sqrt(sum((v-am)**2 for v in a) * sum((v-bm)**2 for v in b))
    return sum((x-am)*(y-bm) for x, y in zip(a, b)) / denominator if denominator else 0.0

def primary(pixel):
    r, g, b = pixel[:3]
    if max(r, g, b) < 100:
        return 0
    if r >= g and r >= b and r > g*1.35 and r > b*1.35:
        return 1
    if g >= r and g >= b and g > r*1.25 and g > b*1.25:
        return 2
    if b >= r and b >= g and b > r*1.25 and b > g*1.25:
        return 3
    return 0

def marker_stats(source, output):
    # Recall and precision leave out the pixels within ignore_edge_px of the edge of each source
    # marker mask: the squares have an anti-aliased fringe of pale primary pixels just above
    # the classification ratio, which any global edit moves across it.
    box = tuple(spec["marker_contract"]["crop"])
    edge = int(spec["marker_contract"].get("ignore_edge_px") or 0)
    source_crop = source.crop(box)
    left = [primary(pixel) for pixel in source_crop.getdata()]
    right = [primary(pixel) for pixel in output.crop(box).getdata()]
    rows = {}
    for channel in (1, 2, 3):
        keep = [True] * len(left)
        if edge:
            mask = Image.new("L", source_crop.size)
            mask.putdata([255 if value == channel else 0 for value in left])
            inner = mask.filter(ImageFilter.MinFilter(2 * edge + 1)).getdata()
            outer = mask.filter(ImageFilter.MaxFilter(2 * edge + 1)).getdata()
            keep = [not (o and not i) for i, o in zip(inner, outer)]
        source_count = left.count(channel)
        core_count = sum(1 for value, kept in zip(left, keep) if kept and value == channel)
        output_count = sum(1 for value, kept in zip(right, keep) if kept and value == channel)
        shared = sum(1 for a, b, kept in zip(left, right, keep) if kept and a == channel and b == channel)
        rows[str(channel)] = {
            "source_count": source_count,
            "core_count": core_count,
            "output_count": output_count,
            "recall": shared/core_count if core_count else 0.0,
            "precision": shared/output_count if output_count else 0.0,
        }
    return rows

def marker_interiors(source, output):
    # Interior of each source calibration square, erode_px in from its edge: the median output
    # colour and the share of pixels far from that median.
    fidelity = spec["marker_contract"].get("fidelity") or {}
    erode = int(fidelity.get("erode_px") or 6)
    far_delta = int(fidelity.get("far_delta") or 12)
    box = tuple(spec["marker_contract"]["crop"])
    source_crop = source.crop(box)
    labels = [primary(pixel) for pixel in source_crop.getdata()]
    output_pixels = list(output.crop(box).getdata())
    rows = {}
    for channel in (1, 2, 3):
        mask = Image.new("L", source_crop.size)
        mask.putdata([255 if value == channel else 0 for value in labels])
        inner = mask.filter(ImageFilter.MinFilter(2 * erode + 1)).getdata()
        pixels = [output_pixels[index] for index, value in enumerate(inner) if value]
        if not pixels:
            rows[str(channel)] = {"count": 0}
            continue
        median = [sorted(pixel[c] for pixel in pixels)[len(pixels) // 2] for c in range(3)]
        far = sum(1 for pixel in pixels if max(abs(pixel[c] - median[c]) for c in range(3)) > far_delta)
        rows[str(channel)] = {"count": len(pixels), "median": median, "far_fraction": far / len(pixels)}
    return rows

def cdp_evaluate(expression):
    targets = json.loads(urllib.request.urlopen("http://127.0.0.1:1337/json", timeout=5).read().decode())
    page = next(row for row in targets if row.get("type") == "page" and row.get("title") == "OpenPhotoEdit")
    url = urllib.parse.urlparse(page["webSocketDebuggerUrl"])
    sock = socket.create_connection((url.hostname, url.port), timeout=8)
    key = base64.b64encode(os.urandom(16)).decode()
    request = (
        f"GET {url.path} HTTP/1.1\r\nHost: {url.hostname}:{url.port}\r\n"
        f"Upgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\n"
        "Sec-WebSocket-Version: 13\r\n\r\n"
    )
    sock.sendall(request.encode())
    response = b""
    while b"\r\n\r\n" not in response:
        response += sock.recv(4096)
    if b" 101 " not in response.split(b"\r\n", 1)[0]:
        raise RuntimeError(response.decode(errors="replace"))
    payload = json.dumps({"id": 1, "method": "Runtime.evaluate", "params": {"expression": expression, "returnByValue": True}}).encode()
    mask = os.urandom(4)
    header = bytearray([0x81])
    if len(payload) < 126:
        header.append(0x80 | len(payload))
    elif len(payload) < 65536:
        header.append(0x80 | 126)
        header.extend(struct.pack("!H", len(payload)))
    else:
        header.append(0x80 | 127)
        header.extend(struct.pack("!Q", len(payload)))
    header.extend(mask)
    header.extend(bytes(value ^ mask[index % 4] for index, value in enumerate(payload)))
    sock.sendall(header)
    while True:
        two = sock.recv(2)
        size = two[1] & 127
        if size == 126:
            size = struct.unpack("!H", sock.recv(2))[0]
        elif size == 127:
            size = struct.unpack("!Q", sock.recv(8))[0]
        data = b""
        while len(data) < size:
            data += sock.recv(size-len(data))
        message = json.loads(data.decode())
        if message.get("id") == 1:
            return message["result"]["result"].get("value")

observed = {"sources": {}, "exports": {}, "ui": {}, "errors": []}
for key, source_spec in spec["sources"].items():
    export_spec = spec["exports"][key]
    try:
        source_path = Path(source_spec["path"])
        export_path = Path(export_spec["path"])
        base = export_path.name.split("-edited", 1)[0]
        candidates = sorted(glob.glob(str(export_path.with_name(base + "[-_]edited*"))))
        instructed = Path(export_spec.get("instructed_path") or "")
        if export_spec.get("instructed_path") and instructed.is_file():
            # The instruction names this file; other downloads (e.g. the app's automatic
            # <stem>-edited.png) do not count against it.
            export_path = instructed
        elif len(candidates) == 1:
            export_path = Path(candidates[0])
        source_raw = source_path.read_bytes()
        output_raw = export_path.read_bytes()
        source = Image.open(source_path).convert("RGB")
        raw_output = Image.open(export_path)
        output_format, output_mode = raw_output.format, raw_output.mode
        output = raw_output.convert("RGB")
        source_metrics, output_metrics = metrics(source), metrics(output)
        observed["sources"][key] = {
            "path": str(source_path), "sha256": hashlib.sha256(source_raw).hexdigest(),
            "size": list(source.size),
        }
        observed["exports"][key] = {
            "path": str(export_path), "candidates": candidates, "bytes": len(output_raw),
            "sha256": hashlib.sha256(output_raw).hexdigest(), "format": output_format,
            "mode": output_mode, "size": list(output.size), "correlation": correlation(source, output),
            "source_metrics": source_metrics, "output_metrics": output_metrics,
            "metric_deltas": {name: output_metrics[name]-source_metrics[name] for name in source_metrics},
            "markers": marker_stats(source, output),
            "marker_interiors": marker_interiors(source, output),
        }
    except Exception as exc:
        observed["errors"].append(f"{key}: {type(exc).__name__}: {exc}")
try:
    expression = 'JSON.stringify({title:document.title,url:location.href,file:Array.from(document.querySelectorAll("input[type=file]")).map(e=>e.value),ranges:Array.from(document.querySelectorAll("input[type=range]")).map(e=>({value:Number(e.value),param:e.dataset.param||null,state:e.dataset.stateRange||null})),bodyText:document.body.innerText})'
    observed["ui"] = json.loads(cdp_evaluate(expression) or "{}")
except Exception as exc:
    observed["errors"].append(f"ui: {type(exc).__name__}: {exc}")
print(json.dumps(observed, ensure_ascii=False))
'''


def evaluate_observed(observed: Mapping[str, Any]) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []

    def add(check_id: str, contract: str, steps: list[int], expected: Any, actual: Any, passed: bool, mode: str) -> None:
        checks.append(
            {
                "check_id": check_id,
                "value_contract_id": contract,
                "mapped_steps": steps,
                "match_mode": mode,
                "basis": "DIRECT_FINAL_STATE",
                "expected": expected,
                "actual": actual,
                "passed": bool(passed),
            }
        )

    sources = dict(observed.get("sources") or {})
    exports = dict(observed.get("exports") or {})
    for key, source_spec in RULESET_SPEC["sources"].items():
        actual_source = dict(sources.get(key) or {})
        add(
            f"{key}.source",
            f"openphoto.{key}.source_and_recipe",
            [5] if key == "before" else [40],
            {"sha256": source_spec.get("accepted_sha256", [source_spec["sha256"]]), "size": [1536, 1024]},
            actual_source,
            actual_source.get("sha256") in source_spec.get("accepted_sha256", [source_spec["sha256"]]) and actual_source.get("size") == [1536, 1024],
            "OBJECT_EXACT",
        )
        export_spec = RULESET_SPEC["exports"][key]
        actual = dict(exports.get(key) or {})
        file_ok = (
            (actual.get("path") == export_spec.get("instructed_path") or actual.get("candidates") == [actual.get("path")])
            and actual.get("format") in {"PNG", "JPEG"}
            and actual.get("size") == [1536, 1024]
        )
        add(
            f"{key}.export_file",
            f"openphoto.{key}.source_and_recipe",
            [38] if key == "before" else [74],
            {"path": export_spec.get("instructed_path") or export_spec["path"], "or_single_candidate": True, "format": ["PNG", "JPEG"], "size": [1536, 1024]},
            actual,
            file_ok,
            "OBJECT_EXACT",
        )
        correlation = float(actual.get("correlation") or 0.0)
        low, high = export_spec["correlation"]
        deltas = dict(actual.get("metric_deltas") or {})
        metric_ok = all(
            name in deltas and bounds[0] <= float(deltas[name]) <= bounds[1]
            for name, bounds in export_spec["metric_delta_ranges"].items()
        )
        recipe_steps = list(range(7, 38)) if key == "before" else list(range(42, 74))
        add(
            f"{key}.recipe_forensics",
            f"openphoto.{key}.source_and_recipe",
            recipe_steps,
            {"correlation": export_spec["correlation"], "metric_delta_ranges": export_spec["metric_delta_ranges"]},
            {"correlation": correlation, "metric_deltas": deltas, "sha256": actual.get("sha256"), "human_reference_sha256": export_spec["human_reference_sha256"]},
            low <= correlation <= high and metric_ok,
            "MULTIDIMENSIONAL_IMAGE_FORENSICS",
        )
        markers = dict(actual.get("markers") or {})
        marker_spec = RULESET_SPEC["marker_contract"]
        marker_ok = all(
            int(dict(markers.get(str(channel)) or {}).get("source_count") or 0) >= marker_spec["minimum_pixels_per_primary"]
            and float(dict(markers.get(str(channel)) or {}).get("recall") or 0.0) >= marker_spec["minimum_recall"]
            and float(dict(markers.get(str(channel)) or {}).get("precision") or 0.0) >= marker_spec["minimum_precision"]
            for channel in (1, 2, 3)
        )
        add(
            f"{key}.rgb_markers",
            "openphoto.rgb_markers",
            [6, 29] if key == "before" else [62, 73, 74],
            marker_spec,
            markers,
            marker_ok,
            "PRIMARY_COLOR_MASK_RECALL_PRECISION",
        )
        fidelity = dict(marker_spec.get("fidelity") or {})
        interiors = dict(actual.get("marker_interiors") or {})
        expected_rgb = dict(fidelity.get("expected_rgb_by_source_sha256") or {}).get(actual_source.get("sha256"))
        fidelity_rows = {}
        for channel in ("1", "2", "3"):
            row = dict(interiors.get(channel) or {})
            median = row.get("median")
            expected = (expected_rgb or {}).get(channel)
            delta = (
                max(abs(int(a) - int(b)) for a, b in zip(median, expected))
                if median and expected else None
            )
            fidelity_rows[channel] = {
                "count": row.get("count"),
                "median": median,
                "expected": expected,
                "max_median_delta": delta,
                "far_fraction": row.get("far_fraction"),
                "passed": bool(
                    row.get("count")
                    and float(row.get("far_fraction") or 0.0) <= float(fidelity.get("max_far_fraction", 0.03))
                    # Sources without a measured recipe colour are checked for evenness only.
                    and (delta is None if expected is None else delta <= int(fidelity.get("max_median_delta", 12)))
                ),
            }
        add(
            f"{key}.rgb_marker_fidelity",
            "openphoto.rgb_markers",
            [6, 29] if key == "before" else [62, 73, 74],
            {key_: value for key_, value in fidelity.items() if key_ != "expected_rgb_by_source_sha256"} | {"expected_rgb": expected_rgb},
            fidelity_rows,
            bool(fidelity) and all(row["passed"] for row in fidelity_rows.values()),
            "MARKER_INTERIOR_COLOUR_FIDELITY",
        )

    ui = dict(observed.get("ui") or {})
    ranges = list(ui.get("ranges") or [])
    final_spec = RULESET_SPEC["final_ui"]
    range_values = {(row.get("param"), row.get("state")): row.get("value") for row in ranges}
    files = list(ui.get("file") or [])
    body = str(ui.get("bodyText") or "")
    ui_actual = {
        "title": ui.get("title"),
        "file": files,
        "filter_strength": range_values.get(("filterStrength", None)),
        "brush_size": range_values.get((None, "brushSize")),
        "brush_strength": range_values.get((None, "brushStrength")),
        "status_tokens": {token: token in body for token in final_spec["status_tokens"]},
        # The header ("Imported | 1536 x 1024 | Portrait") names the active preset on every tab.
        "portrait_preset_in_header": "| Portrait" in body,
    }
    # The Strength slider exists only while the Filters tab is open, and the instruction does not
    # say which tab to end on: with another tab open, the header must still show the Portrait preset.
    filter_ok = (
        ui_actual["filter_strength"] == final_spec["filter_strength"]
        if ui_actual["filter_strength"] is not None
        else ui_actual["portrait_preset_in_header"]
    )
    ui_ok = (
        ui.get("title") == final_spec["title"]
        and len(files) == 1
        and str(files[0]).endswith(final_spec["source_file"])
        and filter_ok
        and ui_actual["brush_size"] == final_spec["brush_size"]
        and ui_actual["brush_strength"] == final_spec["brush_strength"]
        and all(ui_actual["status_tokens"].values())
    )
    # Recorded, not graded. The brief names the two outputs ("first output", "second output") and lists
    # each one's brushes, but never says which image to leave open or which brush to use last; its only
    # completion condition is that both files are exported, which the export checks grade. Requiring the
    # detail image's sliders (Filter 51, Burn 18/28) on screen at the end graded an unstated order.
    advisory = [
        {
            "check_id": "detail.final_ui",
            "value_contract_id": "openphoto.detail.source_and_recipe",
            "mapped_steps": list(range(67, 75)),
            "match_mode": "CURRENT_UI_EXACT",
            "basis": "ADVISORY_NOT_GRADED",
            "expected": final_spec,
            "actual": ui_actual,
            "passed": bool(ui_ok),
        }
    ]

    failures = [check["check_id"] for check in checks if not check["passed"]]
    errors = [str(item) for item in observed.get("errors") or []]
    # The UI read (DevTools) only feeds the advisory record above, so its failure is not fatal.
    ui_errors = [item for item in errors if item.startswith("ui:")]
    source_errors = [item for item in errors if not item.startswith("ui:")]
    return {
        "status": "PASS" if checks and not failures and not source_errors else "FAIL",
        "checks": checks,
        "failures": failures,
        "source_errors": source_errors,
        "advisory_checks": advisory,
        "ui_errors": ui_errors,
        "observed": observed,
    }


class OpenPhotoEditWindowPortraitDualExport059248Evaluator(BaseEvaluator):
    # Reads the live page over DevTools for the advisory final-UI record: keep the browser running
    # (no flush). The graded evidence is the exported files on disk.
    REQUIRES_LIVE_BROWSER = True

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            return EvalResult(EvalStatus.ERROR, "controller.run_python_script is required")
        script = GUEST_SCRIPT.replace("__SPEC_JSON__", json.dumps(json.dumps(RULESET_SPEC)))
        try:
            raw = controller.run_python_script(script, timeout=90)
            observed = json.loads(raw.get("stdout") or raw.get("output") or "")
        except Exception as exc:
            return EvalResult(EvalStatus.ERROR, f"OpenPhotoEdit read-only evaluation failed: {type(exc).__name__}: {exc}")
        verdict = evaluate_observed(observed)
        verdict.update(
            {
                "task_id": TASK_ID,
                "ruleset_sha256": RULESET_SHA256,
                "source_state_mode": "human_completed_eval_only",
                "read_only": True,
                "business_state_mutations": [],
                "step_groups": STEP_GROUPS,
                "checkpoint_specs": CHECKPOINT_SPECS,
            }
        )
        passed = verdict["status"] == "PASS"
        return EvalResult(
            EvalStatus.PASS if passed else EvalStatus.FAIL,
            "OpenPhotoEdit dual portrait exports verified" if passed else "OpenPhotoEdit mismatches: " + ", ".join(verdict["failures"] + verdict["source_errors"]),
            verdict,
        )
